-- ==========================================================================
-- B4 FOLLOW-ON FIX (mapping): mapping: one duplicate rewrite
--
-- Courses: mapping. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/mapping.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql mapping. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- mapping advanced final - ord 7
  select case when md5(prompt) = 'c219468ab022d5f186b9dc64709630f6' and md5(coalesce(explanation, '')) = '4f419cc13859c968c513f9d5a1491a34' and md5(options::text) = md5('["The bending energy penalty the thin-plate spline applies between control points.", "The extrapolation error of a five-well map at a location on its boundary.", "The mismatch between the well spacing and the scale of the structure.", "The difference between a five-well map and a six-well map at a single node."]'::jsonb::text) and answer_index = 2 then 'old'
              when md5(prompt) = 'b321073931a9ed7cc03c1e3d31948c5f' and md5(coalesce(explanation, '')) = 'bfd25bb6595d92b5d2da23e183cf55f4' and md5(options::text) = md5('["About 2 percent, since 9.84 m is small beside a 1546 m depth.", "About 50 percent, because the five-well map misses half of the structure at the crest.", "About 20 percent, nearly 10 m of the 49 m relief.", "Too small to matter, since a residual is judged against the pick uncertainty rather than the relief."]'::jsonb::text) and answer_index = 2 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'mapping' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 7 and active;
  if v_state is null then raise exception 'B4 fix mapping refused: no row for mapping advanced final - ord 7'; end if;
  if v_state = 'other' then raise exception 'B4 fix mapping refused: mapping advanced final - ord 7 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'How large is the Ekene-6 leave-one-out residual against the structural relief across the six picks?', options = '["About 2 percent, since 9.84 m is small beside a 1546 m depth.", "About 50 percent, because the five-well map misses half of the structure at the crest.", "About 20 percent, nearly 10 m of the 49 m relief.", "Too small to matter, since a residual is judged against the pick uncertainty rather than the relief."]'::jsonb,
           answer_index = 2, explanation = 'The six picks span 49 m, from 1541 m to 1590 m, and the five-well map missed Ekene-6 by +9.84 m, so a single prediction was wrong by 20 percent of the relief the map exists to describe. Set against the 1546 m depth it looks small, but depth is the wrong yardstick for a structure map.'
     where app_slug = 'mapping' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 7 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix mapping refused: mapping advanced final - ord 7 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'mapping' and active;
  if v_total <> 396 then raise exception 'B4 fix mapping refused: mapping holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix mapping: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
